module.exports=course('js-dom-async',units,paths.map(([id,title,path])=>({id,title:'MDN: '+title,url:'https://github.com/mdn/content/blob/'+commit+'/'+path,source:{repo:'mdn/content',commit,path,verification:'Pinned official MDN source; browser-specific claims require browser evidence distinct from Node fixtures.'}})));
